import type { Lang } from './index'

/**
 * English catalogue content, generated by `npm run data` into src/data/en.json as
 * `{ records: { [id]: { ...English fields } }, market: { ... } }`. Read through a glob so the app still
 * builds (and shows Thai) before that file exists or while it's partial.
 */
interface EnData {
  records?: Record<string, Record<string, unknown>>
  market?: Record<string, unknown>
}

const files = import.meta.glob<EnData>('../data/en.json', { eager: true, import: 'default' })
const EN: EnData = Object.values(files)[0] ?? {}

/** True when English text exists for this catalogue record. */
export const hasEnglish = (id: string) => !!EN.records?.[id]

/**
 * The record with its English fields laid over the Thai ones when `lang` is 'en'. Objects merge key by
 * key at any depth, and arrays of objects merge item by item (the English trims carry only `name`,
 * `hand`, `compute`, so prices and specs stay; gallery items gain only `alt`). Arrays of strings are
 * replaced whole. Anything not translated (missing, null or empty) stays Thai.
 */
export function localized<T extends { id: string }>(record: T, lang: Lang): T {
  if (lang !== 'en') return record
  const extra = EN.records?.[record.id]
  return extra ? (overlay(record, extra) as T) : record
}

/** Market data (guide content) with English overlaid in the same way. */
export function localizedMarket<T extends object>(market: T, lang: Lang): T {
  return lang === 'en' && EN.market ? (overlay(market, EN.market) as T) : market
}

const isPlain = (v: unknown): v is Record<string, unknown> => !!v && typeof v === 'object' && !Array.isArray(v)

function overlay(base: unknown, extra: unknown): unknown {
  if (extra == null || extra === '') return base
  if (Array.isArray(base) && Array.isArray(extra)) {
    if (base.some(isPlain) && extra.some(isPlain)) return base.map((b, i) => (i < extra.length ? overlay(b, extra[i]) : b))
    return extra
  }
  if (isPlain(base) && isPlain(extra)) {
    const out: Record<string, unknown> = { ...base }
    for (const [k, v] of Object.entries(extra)) out[k] = overlay(base[k], v)
    return out
  }
  return extra
}
